//! The `RccPeripheral` trait: clock enable/reset/bus frequency for named peripheral
//! singletons (simplified version of the ch32-hal scheme).
//!
//! Concrete implementations are generated by the `impl_rcc!` macro table in `rcc.rs`.

use crate::time::Hertz;

/// A peripheral singleton that carries clock tree information.
///
/// The frequency source used by `frequency()` is specified per bus in the macro table:
/// GPIO/DMA and the like hang off the AHB (`hclk`); when the APB divider is > 1, the
/// timer peripheral clock is 2x the APB clock (`pclk1_tim` / `pclk2_tim`), while the
/// remaining APB peripherals use `pclk1` / `pclk2`.
pub trait RccPeripheral: crate::embassy_hal_internal::PeripheralType + 'static {
    /// The input clock frequency of this peripheral.
    fn frequency() -> Hertz;

    /// Enables the peripheral clock and pulses the reset (set the RST bitfield, then clear it).
    fn enable_and_reset();

    /// Disables the peripheral clock.
    fn disable();
}
